package br.com.sergio.gestaopedidos.service;
import br.com.sergio.gestaopedidos.dto.estoque.*;import br.com.sergio.gestaopedidos.entity.*;import br.com.sergio.gestaopedidos.enums.*;import br.com.sergio.gestaopedidos.exception.*;import br.com.sergio.gestaopedidos.repository.*;import org.junit.jupiter.api.Test;import java.lang.reflect.Proxy;import java.math.BigDecimal;import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.*;
class EstoqueServiceTest{
 @Test void custosMediosSeparadosESaidas(){Fake f=new Fake();f.addInsumo(1,UnidadeMedida.QUILOGRAMA,true);f.addProduto(2,UnidadeVenda.UNIDADE,TipoProduto.PRODUTO_REVENDA,true);EstoqueService s=f.service();s.registrarEntradaManual(f.entrada(TipoItemEstoque.INSUMO,1,"10","100"));s.registrarEntradaManual(f.entrada(TipoItemEstoque.INSUMO,1,"10","200"));s.registrarEntradaManual(f.entrada(TipoItemEstoque.PRODUTO_REVENDA,2,"4","80"));assertThat(f.saldo(TipoItemEstoque.INSUMO,1).getCustoMedioAtual()).isEqualByComparingTo("15.000000");assertThat(f.saldo(TipoItemEstoque.PRODUTO_REVENDA,2).getCustoMedioAtual()).isEqualByComparingTo("20.000000");s.registrarSaidaManual(f.saida(TipoItemEstoque.INSUMO,1,"5"));assertThat(f.saldo(TipoItemEstoque.INSUMO,1).getValorTotalEstoque()).isEqualByComparingTo("225.00");}
 @Test void validaProduzidoSaldoEUnidade(){Fake f=new Fake();f.addProduto(2,UnidadeVenda.UNIDADE,TipoProduto.PREPARACAO_PRODUZIDA,true);EstoqueService s=f.service();assertThatThrownBy(()->s.registrarEntradaManual(f.entrada(TipoItemEstoque.PRODUTO_REVENDA,2,"1","10"))).hasMessageContaining("revenda");f.addInsumo(1,UnidadeMedida.UNIDADE,true);s.registrarEntradaManual(f.entrada(TipoItemEstoque.INSUMO,1,"2","20"));assertThatThrownBy(()->s.registrarSaidaManual(f.saida(TipoItemEstoque.INSUMO,1,"3"))).hasMessageContaining("Estoque insuficiente");assertThatThrownBy(()->s.registrarEntradaManual(f.entrada(TipoItemEstoque.INSUMO,1,"1.5","10"))).hasMessageContaining("inteira");}
 @Test void producaoConsomeInsumoEEntraProdutoComCustoReal(){Fake f=new Fake();f.addInsumo(1,UnidadeMedida.QUILOGRAMA,true);f.addProduto(2,UnidadeVenda.UNIDADE,TipoProduto.PREPARACAO_PRODUZIDA,true);EstoqueService s=f.service();s.registrarEntradaManual(f.entrada(TipoItemEstoque.INSUMO,1,"10","80"));Producao p=producao(f.produtos.get(2L),"20");ItemProducao item=p.getItens().getFirst();s.processarProducao(p,Map.of(2L,Map.of(f.insumos.get(1L),new BigDecimal("6.000"))));SaldoEstoque produto=f.saldo(TipoItemEstoque.PREPARACAO_PRODUZIDA,2);assertThat(f.saldo(TipoItemEstoque.INSUMO,1).getQuantidadeAtual()).isEqualByComparingTo("4.000");assertThat(produto.getQuantidadeAtual()).isEqualByComparingTo("20.000");assertThat(produto.getValorTotalEstoque()).isEqualByComparingTo("48.00");assertThat(produto.getCustoMedioAtual()).isEqualByComparingTo("2.400000");assertThat(item.getCustoTotal()).isEqualByComparingTo("48.00");assertThat(item.getCustoUnitario()).isEqualByComparingTo("2.400000");MovimentacaoEstoque entrada=f.movimentos.stream().filter(m->m.getTipo()==TipoMovimentacaoEstoque.ENTRADA_PRODUCAO).findFirst().orElseThrow();assertThat(entrada.getValorTotal()).isEqualByComparingTo("48.00");assertThat(entrada.getCustoUnitario()).isEqualByComparingTo("2.400000");}
 @Test void producaoRecalculaCustoMedioPonderadoEArredondaLote(){Fake f=new Fake();f.addInsumo(1,UnidadeMedida.QUILOGRAMA,true);f.addProduto(2,UnidadeVenda.UNIDADE,TipoProduto.PREPARACAO_PRODUZIDA,true);EstoqueService s=f.service();s.registrarEntradaManual(f.entrada(TipoItemEstoque.INSUMO,1,"3","10"));Producao primeira=producao(f.produtos.get(2L),"2");s.processarProducao(primeira,Map.of(2L,Map.of(f.insumos.get(1L),new BigDecimal("0.999"))));assertThat(primeira.getItens().getFirst().getCustoTotal()).isEqualByComparingTo("3.33");s.registrarEntradaManual(f.entrada(TipoItemEstoque.INSUMO,1,"3","18"));Producao segunda=producao(f.produtos.get(2L),"1");s.processarProducao(segunda,Map.of(2L,Map.of(f.insumos.get(1L),BigDecimal.ONE)));SaldoEstoque saldo=f.saldo(TipoItemEstoque.PREPARACAO_PRODUZIDA,2);assertThat(saldo.getQuantidadeAtual()).isEqualByComparingTo("3.000");assertThat(saldo.getValorTotalEstoque()).isEqualByComparingTo("8.26");assertThat(saldo.getCustoMedioAtual()).isEqualByComparingTo("2.753333");}
 @Test void producaoMultiplaAgrupaSaidaEDistribuiCustosDosLotes(){Fake f=new Fake();f.addInsumo(1,UnidadeMedida.QUILOGRAMA,true);f.addProduto(2,UnidadeVenda.UNIDADE,TipoProduto.PREPARACAO_PRODUZIDA,true);f.addProduto(3,UnidadeVenda.UNIDADE,TipoProduto.PREPARACAO_PRODUZIDA,true);EstoqueService s=f.service();s.registrarEntradaManual(f.entrada(TipoItemEstoque.INSUMO,1,"10","80"));Producao p=Producao.builder().id(91L).build();p.adicionarItem(ItemProducao.builder().produto(f.produtos.get(2L)).nomeHistorico("Produto 2").unidadeHistorica(UnidadeMedida.UNIDADE).quantidade(new BigDecimal("2")).build());p.adicionarItem(ItemProducao.builder().produto(f.produtos.get(3L)).nomeHistorico("Produto 3").unidadeHistorica(UnidadeMedida.UNIDADE).quantidade(new BigDecimal("4")).build());s.processarProducao(p,Map.of(2L,Map.of(f.insumos.get(1L),new BigDecimal("2")),3L,Map.of(f.insumos.get(1L),new BigDecimal("3"))));assertThat(f.movimentos).filteredOn(m->m.getTipo()==TipoMovimentacaoEstoque.SAIDA_CONSUMO_PRODUCAO).singleElement().extracting(MovimentacaoEstoque::getQuantidade).isEqualTo(new BigDecimal("5.000"));assertThat(p.getItens().get(0).getCustoTotal()).isEqualByComparingTo("16.00");assertThat(p.getItens().get(1).getCustoTotal()).isEqualByComparingTo("24.00");assertThat(f.saldo(TipoItemEstoque.PREPARACAO_PRODUZIDA,2).getCustoMedioAtual()).isEqualByComparingTo("8.000000");assertThat(f.saldo(TipoItemEstoque.PREPARACAO_PRODUZIDA,3).getCustoMedioAtual()).isEqualByComparingTo("6.000000");}
 @Test void producaoComFaltaNaoCriaMovimento(){Fake f=new Fake();f.addInsumo(1,UnidadeMedida.QUILOGRAMA,true);f.addProduto(2,UnidadeVenda.UNIDADE,TipoProduto.PREPARACAO_PRODUZIDA,true);EstoqueService s=f.service();s.registrarEntradaManual(f.entrada(TipoItemEstoque.INSUMO,1,"1","8"));int antes=f.movimentos.size();Producao p=producao(f.produtos.get(2L),"1");assertThatThrownBy(()->s.processarProducao(p,Map.of(2L,Map.of(f.insumos.get(1L),new BigDecimal("2"))))).hasMessageContaining("faltando");assertThat(f.movimentos).hasSize(antes);assertThat(f.saldo(TipoItemEstoque.INSUMO,1).getQuantidadeAtual()).isEqualByComparingTo("1.000");assertThat(f.saldo(TipoItemEstoque.PREPARACAO_PRODUZIDA,2)).isNull();}
 @Test void previaEConfirmacaoCompartilhamComposicaoConsolidadaECustoHistorico(){Fake f=new Fake();f.addInsumo(1,UnidadeMedida.UNIDADE,true);f.addProduto(2,UnidadeVenda.QUILOGRAMA,TipoProduto.PREPARACAO_PRODUZIDA,true);f.addProduto(3,UnidadeVenda.UNIDADE,TipoProduto.PRODUTO_COMERCIAL,true);f.produtos.get(3L).setPreco(new BigDecimal("40"));f.compor(3L,ItemComposicaoProduto.builder().tipoComponente(TipoComponenteComposicao.PREPARACAO_PRODUZIDA).preparacao(f.produtos.get(2L)).nomeHistorico("Feijoada").unidadeHistorica(UnidadeMedida.QUILOGRAMA).quantidade(new BigDecimal("0.500")).build(),ItemComposicaoProduto.builder().tipoComponente(TipoComponenteComposicao.INSUMO).insumo(f.insumos.get(1L)).nomeHistorico("Embalagem").unidadeHistorica(UnidadeMedida.UNIDADE).quantidade(BigDecimal.ONE).build());EstoqueService s=f.service();s.registrarEntradaManual(f.entrada(TipoItemEstoque.PREPARACAO_PRODUZIDA,2,"35","350"));s.registrarEntradaManual(f.entrada(TipoItemEstoque.INSUMO,1,"100","200"));ItemPedido item=ItemPedido.builder().produto(f.produtos.get(3L)).quantidade(new BigDecimal("2")).precoUnitario(new BigDecimal("40")).subtotal(new BigDecimal("80")).build();Pedido p=f.pedidoComItens(item);var previa=s.preverPedido(p);assertThat(previa.estoqueSuficiente()).isTrue();assertThat(previa.componentes()).extracting(x->x.nome()+":"+x.necessario()).containsExactly("Insumo 1:2.000","Produto 2:1.000");assertThat(previa.custoEstimado()).isEqualByComparingTo("14.00");assertThat(f.movimentos).filteredOn(m->m.getTipo()==TipoMovimentacaoEstoque.SAIDA_VENDA).isEmpty();s.processarPedido(p);assertThat(item.getCustoTotalHistorico()).isEqualByComparingTo("14.00");assertThat(item.getCustoUnitarioHistorico()).isEqualByComparingTo("7.000000");assertThat(item.getLucroBrutoHistorico()).isEqualByComparingTo("66.00");assertThat(item.getMargemBrutaHistorica()).isEqualByComparingTo("82.5000");assertThat(p.getCustoTotalHistorico()).isEqualByComparingTo("14.00");assertThat(p.getLucroBrutoEstimado()).isEqualByComparingTo("66.00");assertThat(p.getMargemBrutaEstimada()).isEqualByComparingTo("82.5000");s.registrarEntradaManual(f.entrada(TipoItemEstoque.PREPARACAO_PRODUZIDA,2,"1","100"));assertThat(item.getCustoTotalHistorico()).isEqualByComparingTo("14.00");}
 @Test void revendaPorKgCapturaQuantidadeDecimalSemIncluirTaxaNoLucro(){Fake f=new Fake();f.addProduto(2,UnidadeVenda.QUILOGRAMA,TipoProduto.PRODUTO_REVENDA,true);EstoqueService s=f.service();s.registrarEntradaManual(f.entrada(TipoItemEstoque.PRODUTO_REVENDA,2,"15","390"));ItemPedido item=ItemPedido.builder().produto(f.produtos.get(2L)).quantidade(new BigDecimal("1.235")).precoUnitario(new BigDecimal("55.00")).subtotal(new BigDecimal("67.93")).build();Pedido p=f.pedidoComItens(item);p.setTaxaEntrega(new BigDecimal("7.00"));p.setValorTotal(new BigDecimal("74.93"));s.processarPedido(p);assertThat(item.getCustoTotalHistorico()).isEqualByComparingTo("32.11");assertThat(item.getCustoUnitarioHistorico()).isEqualByComparingTo("26.000000");assertThat(p.getLucroBrutoEstimado()).isEqualByComparingTo("35.82");assertThat(p.getMargemBrutaEstimada()).isEqualByComparingTo("52.7308");}
 @Test void subtotalZeroMantemMargensNulas(){ItemPedido item=ItemPedido.builder().quantidade(BigDecimal.ONE).subtotal(BigDecimal.ZERO.setScale(2)).build();item.aplicarCustoHistorico(BigDecimal.ZERO);assertThat(item.getLucroBrutoHistorico()).isEqualByComparingTo("0.00");assertThat(item.getMargemBrutaHistorica()).isNull();Pedido pedido=Pedido.builder().subtotal(BigDecimal.ZERO.setScale(2)).taxaEntrega(new BigDecimal("7.00")).build();pedido.aplicarResultadoHistorico(BigDecimal.ZERO);assertThat(pedido.getLucroBrutoEstimado()).isEqualByComparingTo("0.00");assertThat(pedido.getMargemBrutaEstimada()).isNull();}
 @Test void pedidoHistoricoSemResultadoNaoERecalculadoAutomaticamente(){ItemPedido item=ItemPedido.builder().quantidade(BigDecimal.ONE).subtotal(new BigDecimal("50.00")).custoTotalHistorico(new BigDecimal("7.99")).build();Pedido pedido=Pedido.builder().subtotal(new BigDecimal("50.00")).custoTotalHistorico(new BigDecimal("7.99")).itens(new ArrayList<>(List.of(item))).build();assertThat(item.getLucroBrutoHistorico()).isNull();assertThat(item.getMargemBrutaHistorica()).isNull();assertThat(pedido.getLucroBrutoEstimado()).isNull();assertThat(pedido.getMargemBrutaEstimada()).isNull();}
 @Test void estornoEReaplicacaoRecapturamLucroEMargemNaMesmaOperacao(){Fake f=new Fake();f.addProduto(2,UnidadeVenda.UNIDADE,TipoProduto.PRODUTO_REVENDA,true);EstoqueService s=f.service();s.registrarEntradaManual(f.entrada(TipoItemEstoque.PRODUTO_REVENDA,2,"10","100"));ItemPedido item=ItemPedido.builder().produto(f.produtos.get(2L)).quantidade(BigDecimal.ONE).precoUnitario(new BigDecimal("50.00")).subtotal(new BigDecimal("50.00")).build();Pedido pedido=f.pedidoComItens(item);s.processarPedido(pedido);assertThat(item.getLucroBrutoHistorico()).isEqualByComparingTo("40.00");s.estornarPedido(pedido);s.registrarEntradaManual(f.entrada(TipoItemEstoque.PRODUTO_REVENDA,2,"10","300"));s.processarPedido(pedido);assertThat(item.getCustoTotalHistorico()).isEqualByComparingTo("20.00");assertThat(item.getLucroBrutoHistorico()).isEqualByComparingTo("30.00");assertThat(item.getMargemBrutaHistorica()).isEqualByComparingTo("60.0000");assertThat(pedido.getLucroBrutoEstimado()).isEqualByComparingTo("30.00");}
 @Test void faltaNaPreviaNaoMovimentaENarraNecessarioDisponivelEFaltante(){Fake f=new Fake();f.addProduto(2,UnidadeVenda.UNIDADE,TipoProduto.PRODUTO_REVENDA,true);f.produtos.get(2L).setPreco(BigDecimal.TEN);EstoqueService s=f.service();s.registrarEntradaManual(f.entrada(TipoItemEstoque.PRODUTO_REVENDA,2,"1","5"));Pedido p=f.pedidoComItens(ItemPedido.builder().produto(f.produtos.get(2L)).quantidade(new BigDecimal("2")).precoUnitario(BigDecimal.TEN).subtotal(new BigDecimal("20")).build());assertThat(s.preverPedido(p).estoqueSuficiente()).isFalse();assertThatThrownBy(()->s.processarPedido(p)).hasMessageContaining("Não foi possível iniciar").hasMessageContaining("Necessário: 2 un").hasMessageContaining("Disponível: 1 un").hasMessageContaining("Faltando: 1 un");assertThat(f.saldo(TipoItemEstoque.PRODUTO_REVENDA,2).getQuantidadeAtual()).isEqualByComparingTo("1.000");}
 @Test void compraMantemDataComercialEMovimentosRecebemSeusHorariosReais(){Fake f=new Fake();f.addInsumo(1,UnidadeMedida.QUILOGRAMA,true);ItemCompra item=ItemCompra.builder().id(20L).insumo(f.insumos.get(1L)).nomeHistorico("Insumo 1").unidadeHistorica(UnidadeMedida.QUILOGRAMA).quantidade(new BigDecimal("2.000")).valorTotalItem(new BigDecimal("10.00")).custoUnitario(new BigDecimal("5.000000")).build();LocalDate dataComercial=LocalDate.of(2026,8,4);Compra compra=Compra.builder().id(10L).tipoCompra(TipoCompra.INSUMO).dataCompra(dataComercial).status(StatusCompra.ATIVA).build();compra.adicionarItem(item);EstoqueService s=f.service();LocalDateTime antes=LocalDateTime.now();s.processarCompra(compra);LocalDateTime depoisEntrada=LocalDateTime.now();MovimentacaoEstoque entrada=f.movimentos.getFirst();assertThat(compra.getDataCompra()).isEqualTo(dataComercial);assertThat(entrada.getDataMovimentacao()).isBetween(antes,depoisEntrada);assertThat(entrada.getDataMovimentacao()).isNotEqualTo(dataComercial.atStartOfDay());LocalDateTime antesEstorno=LocalDateTime.now();s.estornarCompra(compra);LocalDateTime depoisEstorno=LocalDateTime.now();MovimentacaoEstoque estorno=f.movimentos.getLast();assertThat(estorno.getTipo()).isEqualTo(TipoMovimentacaoEstoque.ESTORNO_ENTRADA);assertThat(estorno.getDataMovimentacao()).isBetween(antesEstorno,depoisEstorno);assertThat(estorno.getDataMovimentacao()).isAfterOrEqualTo(entrada.getDataMovimentacao());}
 @Test void compraMistaProcessaCadaOrigemComMesmaRegraDeEntradaECustoMedio(){Fake f=new Fake();f.addInsumo(15,UnidadeMedida.QUILOGRAMA,true);f.addProduto(15,UnidadeVenda.UNIDADE,TipoProduto.PRODUTO_REVENDA,true);Compra compra=Compra.builder().id(10L).tipoCompra(TipoCompra.MISTA).dataCompra(LocalDate.now()).status(StatusCompra.ATIVA).build();compra.adicionarItem(ItemCompra.builder().id(20L).insumo(f.insumos.get(15L)).nomeHistorico("Insumo 15").unidadeHistorica(UnidadeMedida.QUILOGRAMA).quantidade(new BigDecimal("2.000")).valorTotalItem(new BigDecimal("20.00")).custoUnitario(new BigDecimal("10.000000")).build());compra.adicionarItem(ItemCompra.builder().id(21L).produto(f.produtos.get(15L)).nomeHistorico("Produto 15").unidadeHistorica(UnidadeMedida.UNIDADE).quantidade(new BigDecimal("3.000")).valorTotalItem(new BigDecimal("45.00")).custoUnitario(new BigDecimal("15.000000")).build());f.service().processarCompra(compra);assertThat(f.movimentos).hasSize(2).extracting(MovimentacaoEstoque::getTipoItem).containsExactly(TipoItemEstoque.INSUMO,TipoItemEstoque.PRODUTO_REVENDA);assertThat(f.saldo(TipoItemEstoque.INSUMO,15).getCustoMedioAtual()).isEqualByComparingTo("10.000000");assertThat(f.saldo(TipoItemEstoque.PRODUTO_REVENDA,15).getCustoMedioAtual()).isEqualByComparingTo("15.000000");}
 private Producao producao(Produto produto,String quantidade){Producao p=Producao.builder().id(90L).build();p.adicionarItem(ItemProducao.builder().produto(produto).nomeHistorico(produto.getNome()).unidadeHistorica(UnidadeMedida.UNIDADE).quantidade(new BigDecimal(quantidade)).build());return p;}
 private Pedido pedido(ItemPedido...itens){return Pedido.builder().id(100L).status(StatusPedido.PENDENTE).estoqueMovimentado(false).itens(new ArrayList<>(List.of(itens))).build();}
 private ItemPedido item(Produto produto,String quantidade){return ItemPedido.builder().id(produto.getId()).produto(produto).quantidade(new BigDecimal(quantidade)).build();}
 static class Fake{final Map<Long,Insumo>insumos=new HashMap<>();final Map<Long,Produto>produtos=new HashMap<>();final Map<Long,ComposicaoProduto>composicoes=new HashMap<>();final Map<String,SaldoEstoque>saldos=new HashMap<>();final List<MovimentacaoEstoque>movimentos=new ArrayList<>();long seq=1;
  void addInsumo(long id,UnidadeMedida u,boolean ativo){insumos.put(id,Insumo.builder().id(id).nome("Insumo "+id).unidadeMedida(u).ativo(ativo).estoqueMinimo(BigDecimal.ZERO).build());}void addProduto(long id,UnidadeVenda u,TipoProduto t,boolean ativo){produtos.put(id,Produto.builder().id(id).nome("Produto "+id).unidadeVenda(u).tipoProduto(t).ativo(ativo).estoqueMinimo(BigDecimal.ZERO).build());}void compor(long produtoId,ItemComposicaoProduto...itens){ComposicaoProduto c=ComposicaoProduto.builder().produtoComercial(produtos.get(produtoId)).ativa(true).build();for(var i:itens)c.adicionarItem(i);composicoes.put(produtoId,c);}Pedido pedidoComItens(ItemPedido...itens){Pedido p=Pedido.builder().id(100L).status(StatusPedido.PENDENTE).estoqueMovimentado(false).subtotal(Arrays.stream(itens).map(ItemPedido::getSubtotal).reduce(BigDecimal.ZERO,BigDecimal::add)).itens(new ArrayList<>(List.of(itens))).build();p.getItens().forEach(i->i.setPedido(p));return p;}String k(TipoItemEstoque t,long id){return t+":"+id;}SaldoEstoque saldo(TipoItemEstoque t,long id){return saldos.get(k(t,id));}
  EstoqueService service(){SaldoEstoqueRepository sr=(SaldoEstoqueRepository)Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{SaldoEstoqueRepository.class},(p,m,a)->switch(m.getName()){case"bloquearInsumo"->Optional.ofNullable(insumos.get(a[0]));case"bloquearProduto"->Optional.ofNullable(produtos.get(a[0]));case"bloquearSaldo","buscarSaldo"->Optional.ofNullable(saldos.get(k((TipoItemEstoque)a[0],(Long)a[1])));case"save"->{SaldoEstoque x=(SaldoEstoque)a[0];Long id=x.getInsumo()!=null?x.getInsumo().getId():x.getProduto().getId();saldos.put(k(x.getTipoItem(),id),x);yield x;}default->zero(m.getReturnType());});MovimentacaoEstoqueRepository mr=(MovimentacaoEstoqueRepository)Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{MovimentacaoEstoqueRepository.class},(p,m,a)->switch(m.getName()){case"save"->{MovimentacaoEstoque x=(MovimentacaoEstoque)a[0];x.setId(seq++);movimentos.add(x);yield x;}case"existsByItemCompraIdAndTipo"->false;case"findByItemCompraCompraIdAndTipoOrderByIdAsc"->movimentos.stream().filter(x->x.getItemCompra()!=null&&x.getItemCompra().getCompra()!=null&&Objects.equals(x.getItemCompra().getCompra().getId(),a[0])&&x.getTipo()==a[1]).toList();case"findByPedidoIdOrderByIdAsc"->movimentos.stream().filter(x->x.getPedido()!=null&&Objects.equals(x.getPedido().getId(),a[0])).toList();default->zero(m.getReturnType());});InsumoService is=new InsumoService(null,null){@Override Insumo buscarEntidade(Long id){var i=insumos.get(id);if(i==null)throw new ResourceNotFoundException("Insumo não encontrado.");return i;}};ProdutoService ps=new ProdutoService(null,null,null){@Override public Produto buscarEntidadePorId(Long id){var p=produtos.get(id);if(p==null)throw new ResourceNotFoundException("Produto não encontrado.");return p;}};ComposicaoProdutoRepository cr=(ComposicaoProdutoRepository)Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{ComposicaoProdutoRepository.class},(p,m,a)->m.getName().equals("findDetailedByProdutoComercialId")?Optional.ofNullable(composicoes.get(a[0])):zero(m.getReturnType()));return new EstoqueService(sr,mr,is,ps,cr);}
  EntradaEstoqueRequest entrada(TipoItemEstoque t,long id,String q,String v){return EntradaEstoqueRequest.builder().tipoItem(t).referenciaId(id).quantidade(new BigDecimal(q)).valorTotal(new BigDecimal(v)).dataMovimentacao(LocalDateTime.now()).build();}SaidaEstoqueRequest saida(TipoItemEstoque t,long id,String q){return SaidaEstoqueRequest.builder().tipoItem(t).referenciaId(id).quantidade(new BigDecimal(q)).tipo(TipoMovimentacaoEstoque.SAIDA_CONSUMO_MANUAL).dataMovimentacao(LocalDateTime.now()).build();}static Object zero(Class<?>t){if(t==boolean.class)return false;if(t==long.class)return 0L;if(t==int.class)return 0;if(Optional.class.isAssignableFrom(t))return Optional.empty();return null;}}
}
